  // Explanation: Robin has a hidden goodwill score; insult is -1, apology and gift are +1, and mood is warm iff the score is positive.
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 1;
    else if (action === "apologise") score += 1;
    else if (action === "gift") score += 1;
  }
  return { mood: score > 0 ? "warm" : "cold" };
}

