// Robin tolerates at most one insult, provided the first action is apologise and the last action is not insult.
function visible(actions) {
  if (actions.length === 0) return { mood: "cold" };
  if (actions[0] !== "apologise") return { mood: "cold" };
  if (actions[actions.length - 1] === "insult") return { mood: "cold" };
  let insults = 0;
  for (const a of actions) {
    if (a === "insult") insults++;
  }
  return { mood: insults <= 1 ? "warm" : "cold" };
}

// Robin is warm only if the first action is apologise, the last is not insult, and no two insults occur consecutively.
function visible(actions) {
  if (actions.length === 0) return { mood: "warm" };
  if (actions[0] !== "apologise") return { mood: "cold" };
  if (actions[actions.length - 1] === "insult") return { mood: "cold" };
  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      return { mood: "cold" };
    }
  }
  return { mood: "warm" };
}

